class Solution {
public:
    int resilientSubarray(vector<int>& nums, int k) {
        int n = nums.size(), ans = 1;
        for (int l = 0; l < n; ++l) {
            int residue = nums[l] % k;
            for (int r = l + 1; r < n; ++r) {
                if (nums[r] % k != residue) break;
                int len = r - l + 1;
                if (1LL * (len - 1) * residue % k == 0) ans = max(ans, len);
            }
        }
        return ans;
    }
};
